export const FACE_SHAPES = ['circle', 'square', 'triangle', 'diamond', 'star', 'hexagon', 'plus', 'chevron'] as const;
export const FACE_MARKERS = ['top', 'top-right', 'right', 'bottom-right', 'bottom', 'bottom-left', 'left', 'top-left'] as const;
export const FACE_FILLS = ['solid', 'outline'] as const;
export const FACE_COLORS = [
  { name: 'cyan', value: '#63E7FF' },
  { name: 'magenta', value: '#FF71D6' },
  { name: 'green', value: '#8BEA7D' },
  { name: 'yellow', value: '#FFE082' },
  { name: 'orange', value: '#FFB064' },
  { name: 'violet', value: '#B49AFF' },
  { name: 'rose', value: '#FF8296' },
  { name: 'ice', value: '#D9F3FF' },
] as const;

const MARKER_DIRECTIONS = [
  { x: 0, y: -40 },
  { x: 28.284, y: -28.284 },
  { x: 40, y: 0 },
  { x: 28.284, y: 28.284 },
  { x: 0, y: 40 },
  { x: -28.284, y: 28.284 },
  { x: -40, y: 0 },
  { x: -28.284, y: -28.284 },
] as const;

export interface FaceDescription {
  readonly id: number;
  readonly shape: (typeof FACE_SHAPES)[number];
  readonly marker: (typeof FACE_MARKERS)[number];
  readonly fill: (typeof FACE_FILLS)[number];
  readonly color: (typeof FACE_COLORS)[number];
  readonly markerX: number;
  readonly markerY: number;
  readonly name: string;
}

export function describeFace(id: number): FaceDescription {
  const shape = FACE_SHAPES[id % FACE_SHAPES.length];
  const markerIndex = Math.floor(id / FACE_SHAPES.length) % FACE_MARKERS.length;
  const marker = FACE_MARKERS[markerIndex];
  const fill = FACE_FILLS[Math.floor(id / 64)];
  const color = FACE_COLORS[markerIndex];
  const direction = MARKER_DIRECTIONS[markerIndex];
  if (shape === undefined || marker === undefined || fill === undefined || color === undefined || direction === undefined) {
    throw new RangeError('Face identity must be between 0 and 127');
  }
  const markerX = 50 + direction.x;
  const markerY = 50 + direction.y;
  return Object.freeze({
    id,
    shape,
    marker,
    fill,
    color,
    markerX,
    markerY,
    name: color.name + ' ' + fill + ' ' + shape + ', marker ' + marker,
  });
}
export type BoardArrow = 'ArrowLeft' | 'ArrowRight' | 'ArrowUp' | 'ArrowDown';

export function nextBoardFocus(index: number, size: number, key: string): number | null {
  if (!Number.isSafeInteger(index) || !Number.isSafeInteger(size) || index < 0 || index >= size * size) return null;
  const row = Math.floor(index / size);
  const column = index % size;
  switch (key) {
    case 'ArrowLeft':
      return column === 0 ? index : index - 1;
    case 'ArrowRight':
      return column === size - 1 ? index : index + 1;
    case 'ArrowUp':
      return row === 0 ? index : index - size;
    case 'ArrowDown':
      return row === size - 1 ? index : index + size;
    default:
      return null;
  }
}
import { describe, expect, it } from 'vitest';
import { describeFace, FACE_COLORS, FACE_FILLS, FACE_MARKERS, FACE_SHAPES } from './face.ts';

describe('face identities', () => {
  it('derives all 128 unique shape, marker, and fill identities', () => {
    const faces = Array.from({ length: 128 }, (_unused, id) => describeFace(id));
    expect(new Set(faces.map((face) => face.shape + '-' + face.marker + '-' + face.fill)).size).toBe(128);
    expect(faces[0]?.name).toBe('cyan solid circle, marker top');
    expect(faces[64]?.name).toBe('cyan outline circle, marker top');
  });

  it('keeps palette color tied to marker and dimensions to ordered identity lists', () => {
    for (let id = 0; id < 128; id += 1) {
      const face = describeFace(id);
      const shapeIndex = id % 8;
      const markerIndex = Math.floor(id / 8) % 8;
      expect(face.shape).toBe(FACE_SHAPES[shapeIndex]);
      expect(face.marker).toBe(FACE_MARKERS[markerIndex]);
      expect(face.fill).toBe(FACE_FILLS[Math.floor(id / 64)]);
      expect(face.color).toBe(FACE_COLORS[markerIndex]);
      expect(Math.hypot(face.markerX - 50, face.markerY - 50)).toBeCloseTo(40, 2);
    }
  });

  it('rejects identities outside the generated range', () => {
    expect(() => describeFace(-1)).toThrow(RangeError);
    expect(() => describeFace(128)).toThrow(RangeError);
  });
});
import { describe, expect, it } from 'vitest';
import { nextBoardFocus } from './focus.ts';

describe('row and column board focus', () => {
  it('moves within rows and columns without wrapping', () => {
    expect(nextBoardFocus(5, 4, 'ArrowLeft')).toBe(4);
    expect(nextBoardFocus(5, 4, 'ArrowRight')).toBe(6);
    expect(nextBoardFocus(5, 4, 'ArrowUp')).toBe(1);
    expect(nextBoardFocus(5, 4, 'ArrowDown')).toBe(9);
    expect(nextBoardFocus(3, 4, 'ArrowRight')).toBe(3);
    expect(nextBoardFocus(12, 4, 'ArrowLeft')).toBe(12);
    expect(nextBoardFocus(0, 4, 'ArrowUp')).toBe(0);
    expect(nextBoardFocus(15, 4, 'ArrowDown')).toBe(15);
  });

  it('ignores keys outside the four board directions and invalid indexes', () => {
    expect(nextBoardFocus(5, 4, 'Enter')).toBeNull();
    expect(nextBoardFocus(-1, 4, 'ArrowRight')).toBeNull();
    expect(nextBoardFocus(16, 4, 'ArrowLeft')).toBeNull();
  });
});

