  expect(invalid.stderr).not.toBe('');
  await writeFile(resolve(directory, 'example-output.json'), valid.stdout, 'utf8');
  await writeFile(resolve(directory, 'invalid-output.txt'), invalid.stderr, 'utf8');
});

