import { useEffect, useState, useSyncExternalStore } from 'react';
import { GameSession } from './dealActions.ts';
import { makeBrowserEnvironment, type SessionView } from './environment.ts';

export interface GameSessionView extends SessionView {
  readonly activateCard: GameSession['activateCard'];
  readonly newGame: GameSession['newGame'];
  readonly restart: GameSession['restart'];
  readonly changeSize: GameSession['changeSize'];
  readonly loadBoard: GameSession['loadBoard'];
  readonly loadSnapshot: GameSession['loadSnapshot'];
  readonly exportSnapshot: GameSession['exportSnapshot'];
  readonly resume: GameSession['resume'];
}

export function useGameSession(): GameSessionView {
  const [session] = useState(() => new GameSession(makeBrowserEnvironment()));
  const view = useSyncExternalStore(session.subscribe, session.getSnapshot, session.getSnapshot);

  useEffect(() => {
    session.start();
    return () => session.stop();
  }, [session]);

  return {
    ...view,
    activateCard: session.activateCard,
    newGame: session.newGame,
    restart: session.restart,
    changeSize: session.changeSize,
    loadBoard: session.loadBoard,
    loadSnapshot: session.loadSnapshot,
    exportSnapshot: session.exportSnapshot,
    resume: session.resume,
  };
}
import { MAX_SEED } from '../board.ts';
import type { GameState } from '../state.ts';
import type { StorageAccess } from './storage.ts';

export interface SessionAnnouncement {
  readonly serial: number;
  readonly text: string;
}

export interface SessionView {
  readonly game: GameState;
  readonly dealId: number;
  readonly paused: boolean;
  readonly best: number | null;
  readonly celebrating: boolean;
  readonly status: string;
  readonly announcement: SessionAnnouncement;
}

export interface SessionEnvironment {
  now(): number;
  setInterval(callback: () => void, milliseconds: number): () => void;
  setTimeout(callback: () => void, milliseconds: number): () => void;
  isVisible(): boolean;
  onVisibilityChange(callback: () => void): () => void;
  readonly storage: StorageAccess | null;
  randomSeed(): number;
}

export function validSeed(environment: SessionEnvironment): number {
  const candidate = environment.randomSeed();
  return Number.isSafeInteger(candidate) && candidate >= 1 && candidate <= MAX_SEED ? candidate : 1;
}

export function makeBrowserEnvironment(): SessionEnvironment {
  let storage: StorageAccess | null = null;
  try { storage = globalThis.localStorage; } catch {
    // Storage may be disabled by the browser.
  }
  return {
    now: () => performance.now(),
    setInterval: (callback, milliseconds) => {
      const id = globalThis.setInterval(callback, milliseconds);
      return () => globalThis.clearInterval(id);
    },
    setTimeout: (callback, milliseconds) => {
      const id = globalThis.setTimeout(callback, milliseconds);
      return () => globalThis.clearTimeout(id);
    },
    isVisible: () => typeof document === 'undefined' || document.visibilityState !== 'hidden',
    onVisibilityChange: (callback) => {
      if (typeof document === 'undefined') return () => undefined;
      document.addEventListener('visibilitychange', callback);
      return () => document.removeEventListener('visibilitychange', callback);
    },
    storage,
    randomSeed: () => {
      try {
        const values = new Uint32Array(1);
        globalThis.crypto.getRandomValues(values);
        const value = values[0];
        if (value !== undefined) return (value % MAX_SEED) + 1;
      } catch {
        // Fresh randomness is best effort; play remains available.
      }
      return Math.floor(Math.random() * MAX_SEED) + 1;
    },
  };
}

import { generateDeck, parseBoardCode, type BoardDescription } from './board.ts';

export const SELECTION_KINDS = ['closed', 'one', 'mismatch'] as const;
export type SelectionKind = (typeof SELECTION_KINDS)[number];

export interface ClosedSelection { readonly kind: 'closed' }
export interface OneSelection { readonly kind: 'one'; readonly index: number }
export interface MismatchSelection {
  readonly kind: 'mismatch';
  readonly first: number;
  readonly second: number;
  readonly remainingMs: number;
}
export type Selection = ClosedSelection | OneSelection | MismatchSelection;

export interface GameState {
  readonly board: BoardDescription;
  readonly deck: readonly number[];
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export const CLOSED_SELECTION: ClosedSelection = Object.freeze({ kind: 'closed' });
export const GAME_LIMITS = Object.freeze({
  mismatchMs: 800,
  maxMoves: 999_999,
  maxElapsedMs: 359_999_999,
});

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  if (board === null) return null;
  return Object.freeze({
    board,
    deck: generateDeck(board),
    matched: Object.freeze([]),
    selection: CLOSED_SELECTION,
    moves: 0,
    elapsedMs: 0,
    started: false,
  });
}

export function matchedPairCount(state: GameState): number {
  return state.matched.length / 2;
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length;
}

export function formatTime(elapsedMs: number): string {
  const totalSeconds = Math.floor(elapsedMs / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = String(totalSeconds % 60).padStart(2, '0');
  return `${minutes}:${seconds}`;
}
export const BOARD_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export const MAX_SEED = 2_147_483_646;
const PARK_MILLER_MODULUS = 2_147_483_647;
const PARK_MILLER_MULTIPLIER = 16_807;
const PARK_MILLER_RANGE = PARK_MILLER_MODULUS - 1;

export interface BoardDescription {
  readonly boardCode: string;
  readonly size: (typeof BOARD_SIZES)[number];
  readonly seed: number;
}

export function isBoardSize(value: unknown): value is (typeof BOARD_SIZES)[number] {
  return typeof value === 'number' && BOARD_SIZES.some((size) => size === value);
}

export function parseBoardCode(value: unknown): BoardDescription | null {
  if (typeof value !== 'string') return null;
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(value);
  if (match === null || match[0] !== value) return null;
  const rawSize = Number(match[1]);
  const seed = Number(match[2]);
  if (!isBoardSize(rawSize) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;
  return Object.freeze({ boardCode: value, size: rawSize, seed });
}

function draw(state: { value: number }, bound: number): number {
  const limit = Math.floor(PARK_MILLER_RANGE / bound) * bound;
  while (true) {
    state.value = (state.value * PARK_MILLER_MULTIPLIER) % PARK_MILLER_MODULUS;
    const candidate = state.value - 1;
    if (candidate < limit) return candidate % bound;
  }
}

export function generateDeck(board: BoardDescription): readonly number[] {
  const cards = board.size * board.size;
  const deck = Array.from({ length: cards }, (_unused, index) => Math.floor(index / 2));
  const generator = { value: board.seed };
  for (let index = cards - 1; index > 0; index -= 1) {
    const other = draw(generator, index + 1);
    const currentFace = deck[index];
    const otherFace = deck[other];
    if (currentFace === undefined || otherFace === undefined) throw new Error('Generated deck index out of range');
    deck[index] = otherFace;
    deck[other] = currentFace;
  }
  return Object.freeze(deck);
}
