    return entries;
  });
  expect(faces).toHaveLength(128);
  expect(new Set(faces.map((face) => face.svg)).size).toBe(128);
  expect(faces.map((face) => face.name).sort()).toEqual(
    Array.from({ length: 128 }, (_unused, id) => describeFace(id).name).sort(),
