import { BOARD_SIZES } from '../board.ts';
import { activateCard } from '../transitions.ts';
import { createGame, isWon, type GameState } from '../state.ts';
import { readBestScores, readPreferences, writeBestScores, type BestScores } from './storage.ts';
import { ActiveClock } from './activeClock.ts';
import { validSeed, type SessionAnnouncement, type SessionEnvironment, type SessionView } from './environment.ts';
import { turnAnnouncement } from './turnAnnouncement.ts';

function boardCode(size: number, seed: number): string {
  return `np1-${size}-${seed}`;
}

const CELEBRATION_MS = 600;

export class SessionController {
  protected game: GameState;
  protected dealId = 0;
  protected paused = false;
  protected celebrating = false;
  protected status = '';
  protected announcement: SessionAnnouncement = Object.freeze({ serial: 0, text: '' });
  protected scores: BestScores;
  protected readonly environment: SessionEnvironment;
  protected readonly clock: ActiveClock;
  private readonly listeners = new Set<() => void>();
  private view: SessionView;
  private clearCelebration: (() => void) | null = null;

  constructor(environment: SessionEnvironment) {
    this.environment = environment;
    const size = readPreferences(environment.storage)?.size ?? BOARD_SIZES[0];
    const first = createGame(boardCode(size, validSeed(environment)));
    if (first === null) throw new Error('Initial supported board could not be created');
    this.game = first;
    this.scores = readBestScores(environment.storage);
    this.view = this.createView();
    this.clock = new ActiveClock(
      environment,
      () => this.game,
      () => this.dealId,
      () => this.paused,
      (game) => { this.game = game; this.publish(); },
    );
  }

  private createView(): SessionView {
    return Object.freeze({
      game: this.game,
      dealId: this.dealId,
      paused: this.paused,
      best: this.scores[this.game.board.size] ?? null,
      celebrating: this.celebrating,
      status: this.status,
      announcement: this.announcement,
    });
  }

  protected publish(): void {
    this.view = this.createView();
    for (const listener of this.listeners) listener();
  }

  readonly subscribe = (listener: () => void): (() => void) => {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  };

  readonly getSnapshot = (): SessionView => this.view;

  start(): void { this.clock.start(); }

  stop(): void {
    this.clock.stop();
    this.clearCelebration?.();
    this.clearCelebration = null;
  }

  protected beginDeal(game: GameState, paused: boolean, status = ''): void {
    this.clearCelebration?.();
    this.clearCelebration = null;
    this.celebrating = false;
    this.game = game;
    this.dealId += 1;
    this.paused = paused;
    this.status = status;
    this.clock.dealChanged();
    this.publish();
  }

  protected announce(text: string, status: string): void {
    this.status = status;
    this.announcement = Object.freeze({ serial: this.announcement.serial + 1, text });
    this.publish();
  }

  readonly activateCard = (index: number): void => {
    if (this.paused) return;
    this.clock.syncNow();
    const before = this.game;
    const after = activateCard(before, index);
    if (after === before) return;
    this.game = after;
    if (before.selection.kind === 'one') {
      const message = turnAnnouncement(before, after);
      if (message !== null) this.announce(message, '');
      if (!isWon(before) && isWon(after)) this.finishPlayedGame(after);
    }
    this.clock.gameChanged();
    this.publish();
  };

  private finishPlayedGame(game: GameState): void {
    const previousBest = this.scores[game.board.size];
    if (previousBest === undefined || game.moves < previousBest) {
      this.scores = Object.freeze({ ...this.scores, [game.board.size]: game.moves });
      writeBestScores(this.environment.storage, this.scores);
    }
    this.celebrating = true;
    const viewDealId = this.dealId;
    this.clearCelebration?.();
    this.clearCelebration = this.environment.setTimeout(() => {
      if (viewDealId !== this.dealId) return;
      this.clearCelebration = null;
      this.celebrating = false;
      this.publish();
    }, CELEBRATION_MS);
  }
}

import { CLOSED_SELECTION, GAME_LIMITS, isWon, type GameState, type MismatchSelection } from './state.ts';

function isCardIndex(state: GameState, index: number): boolean {
  return Number.isSafeInteger(index) && index >= 0 && index < state.deck.length;
}

function hasMatched(state: GameState, index: number): boolean {
  return state.matched.includes(index);
}

function addMove(moves: number): number {
  return Math.min(GAME_LIMITS.maxMoves, moves + 1);
}

export function activateCard(state: GameState, index: number): GameState {
  if (!isCardIndex(state, index) || isWon(state) || hasMatched(state, index)) return state;
  switch (state.selection.kind) {
    case 'closed':
      return Object.freeze({ ...state, started: true, selection: Object.freeze({ kind: 'one', index }) });
    case 'one': {
      if (state.selection.index === index) return state;
      const moves = addMove(state.moves);
      const firstFace = state.deck[state.selection.index];
      const secondFace = state.deck[index];
      if (firstFace === secondFace) {
        const matched = Object.freeze([...state.matched, state.selection.index, index]);
        return Object.freeze({ ...state, matched, moves, selection: CLOSED_SELECTION });
      }
      const selection: MismatchSelection = Object.freeze({
        kind: 'mismatch', first: state.selection.index, second: index, remainingMs: GAME_LIMITS.mismatchMs,
      });
      return Object.freeze({ ...state, moves, selection });
    }
    case 'mismatch':
      return state;
  }
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0 || !state.started || isWon(state)) return state;
  const elapsedMs = Math.min(GAME_LIMITS.maxElapsedMs, state.elapsedMs + milliseconds);
  switch (state.selection.kind) {
    case 'closed':
    case 'one':
      return Object.freeze({ ...state, elapsedMs });
    case 'mismatch':
      if (milliseconds >= state.selection.remainingMs) {
        return Object.freeze({ ...state, elapsedMs, selection: CLOSED_SELECTION });
      }
      return Object.freeze({
        ...state,
        elapsedMs,
        selection: Object.freeze({ ...state.selection, remainingMs: state.selection.remainingMs - milliseconds }),
      });
  }
}
import { generateDeck, parseBoardCode, type BoardDescription } from './board.ts';

export const SELECTION_KINDS = ['closed', 'one', 'mismatch'] as const;
export type SelectionKind = (typeof SELECTION_KINDS)[number];

export interface ClosedSelection { readonly kind: 'closed' }
export interface OneSelection { readonly kind: 'one'; readonly index: number }
export interface MismatchSelection {
  readonly kind: 'mismatch';
  readonly first: number;
  readonly second: number;
  readonly remainingMs: number;
}
export type Selection = ClosedSelection | OneSelection | MismatchSelection;

export interface GameState {
  readonly board: BoardDescription;
  readonly deck: readonly number[];
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export const CLOSED_SELECTION: ClosedSelection = Object.freeze({ kind: 'closed' });
export const GAME_LIMITS = Object.freeze({
  mismatchMs: 800,
  maxMoves: 999_999,
  maxElapsedMs: 359_999_999,
});

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  if (board === null) return null;
  return Object.freeze({
    board,
    deck: generateDeck(board),
    matched: Object.freeze([]),
    selection: CLOSED_SELECTION,
    moves: 0,
    elapsedMs: 0,
    started: false,
  });
}

export function matchedPairCount(state: GameState): number {
  return state.matched.length / 2;
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length;
}

export function formatTime(elapsedMs: number): string {
  const totalSeconds = Math.floor(elapsedMs / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = String(totalSeconds % 60).padStart(2, '0');
  return `${minutes}:${seconds}`;
}

